# Friday: write Eric's weekly slate report into the vault. Both Friday runs
# (15:30 and 17:00) overwrite the same dated file, so the later one includes the
# afternoon's debrief. A report he has to remember to run is the failure this
# system replaces, so the timer writes it.
if ($today.DayOfWeek -eq 'Friday') {
    try {
        $weekArgs = @($PortfolioScript, "week-report", "--end", $today.ToString('yyyy-MM-dd'),
                      "--out", (Join-Path $Vault "Inbox/weekly-slate"))
        if ($SlateRegistry) { $weekArgs += @("--registry", $SlateRegistry) }
        $wout = & $Python @weekArgs 2>&1 | Out-String
        if ($LASTEXITCODE -ne 0) { throw "week-report exited $LASTEXITCODE - $($wout.Trim())" }
        $slateWhy += " | weekly report: Inbox/weekly-slate/$($today.ToString('yyyy-MM-dd')).md"
    }
    catch {
        if ($slateStatus -eq "OK") { $slateStatus = "DUE" }
        $slateWhy += " | weekly report could not be written: $_"
    }
}
$rituals += [pscustomobject]@{
    Name    = "slate"
    Command = "python3 ~/DEV/project-triage/portfolio.py slate-check"
    Last    = $today.ToString('yyyy-MM-dd')
    Days    = 0
    Status  = $slateStatus
    Why     = $slateWhy
}

if ($Json) {
    $rituals | ConvertTo-Json -Depth 4
    exit 0
}

Write-Host ""
Write-Host "== Rituals" -ForegroundColor Cyan
foreach ($r in $rituals) {
    $colour = switch ($r.Status) { "OVERDUE" { "Red" } "DUE" { "Yellow" } "RECHECK" { "Cyan" } default { "DarkGray" } }
    $age = if ($r.Days -ge 9999) { "never run" } else { "$($r.Days)d ago" }
    Write-Host ("  {0,-17} {1,-8} last {2,-12} ({3})" -f $r.Name, $r.Status, $r.Last, $age) -ForegroundColor $colour
}

$due = @($rituals | Where-Object { $_.Status -ne "OK" })
if ($due.Count -eq 0) {
    Write-Host "  all current." -ForegroundColor Green
    exit 0
}

Write-Host ""
foreach ($r in $due) {
    Write-Host ("  -> run {0} — {1}" -f $r.Command, $r.Why) -ForegroundColor Cyan
}

# Desktop prompt. Passive surfacing in a log is what let these freeze for 49
# days in the first place, so when explicitly asked (-Notify) this interrupts.
if ($Notify) {
    # The slate is a rule state, not a ritual age - "last run 0 days ago" would hide
    # what is actually wrong, so it shows its reason instead.
    $lines = $due | ForEach-Object {
        if ($_.Name -eq 'slate') { "SLATE - $($_.Why)" }
        else { "$($_.Command) - last run $($_.Last) ($($_.Days) days ago)" }
    }
    $msg = "KeystoneOS ritual check:`n`n" + ($lines -join "`n") + "`n`nRun it in Claude Code."

    # Windows owns the nudges again since 2026-09-24: Windows is the daytime machine, and
    # the 17:00 / Fri 15:30 prompts fired on a Mac nobody was sitting at. The Mac branch
    # below stays so the script still works there if ownership moves back.
    if ($IsWindows) {
        try {
            & msg.exe $env:USERNAME /TIME:600 $msg 2>&1 | Out-Null
            if ($LASTEXITCODE -ne 0) { throw "msg.exe exited $LASTEXITCODE" }
        }
        catch { Write-Host "  (desktop prompt unavailable: $_)" -ForegroundColor DarkGray }
        exit 0
    }

    # macOS port, 2026-08-15. The Windows original shelled out to msg.exe, which does
    # not exist here - so since the migration EVERY -Notify run fell into the catch and
    # wrote "desktop prompt unavailable" to a log nobody reads. The launchd agent has
    # been firing on schedule into silence. That is the exact invisible-absence failure
    # this whole script was written to prevent, reproduced inside its own alarm.
    #
    # AppleScript has no \n escape: newlines must be spliced with the `return`
    # constant, so build the string as an expression rather than a literal.
    function ConvertTo-AppleScriptExpr([string]$s) {
        $e = $s -replace '\\', '\\' -replace '"', '\"'
        (($e -split "`r?`n") | ForEach-Object { '"' + $_ + '"' }) -join ' & return & '
    }
    $title = if (@($due.Status) -contains 'OVERDUE') { 'KeystoneOS - RITUAL OVERDUE' } else { 'KeystoneOS - ritual due' }
    $bodyExpr  = ConvertTo-AppleScriptExpr $msg
    $titleExpr = ConvertTo-AppleScriptExpr $title
    try {
        # `display dialog` interrupts, which is the point; `giving up after` keeps an
        # unattended machine from wedging on a modal nobody is there to dismiss.
        $cmd = 'display dialog ' + $bodyExpr + ' with title ' + $titleExpr +
               ' buttons {"OK"} default button 1 giving up after 600'
        & /usr/bin/osascript -e $cmd 2>&1 | Out-Null
        if ($LASTEXITCODE -ne 0) { throw "osascript exited $LASTEXITCODE" }
    }
    catch {
        # A launchd agent with no GUI session cannot raise a dialog. Fall back to a
        # notification-centre banner rather than losing the alert entirely.
        try {
            & /usr/bin/osascript -e ('display notification ' + $bodyExpr + ' with title ' + $titleExpr) 2>&1 | Out-Null
            if ($LASTEXITCODE -ne 0) { throw "osascript exited $LASTEXITCODE" }
        }
        catch { Write-Host "  (desktop prompt unavailable: $_)" -ForegroundColor DarkGray }
    }
}

exit 0

# Window is Monday-anchored, not Wednesday-anchored: the first warning should land
# early in the week, with days of runway before Saturday, rather than midweek.
$SeasonStart = [datetime]'2026-08-24'   # Monday of the opening week (season opens Wed 08-26)
$SeasonEnd   = [datetime]'2027-01-23'   # Saturday of the closing week (window ends Wed 01-20),
                                        # so the final week stays actionable through kickoff
$fc = Get-LastRun -Path $CfbSnapshotDir -Filter "*_baylor.csv"
$fcDays = if ($fc) { [int]($today.Date - $fc.Date).TotalDays } else { 9999 }
$inSeason = ($today.Date -ge $SeasonStart.Date) -and ($today.Date -le $SeasonEnd.Date)
# Monday anchors the week. Sunday looks back to the Monday six days gone - i.e. the
# week that Saturday's games just closed out, which is the right week to judge on a
# Sunday (and the answer there is always "nothing to do").
$dow = [int]$today.DayOfWeek            # Sunday=0, Monday=1 .. Saturday=6
$weekMon = $today.Date.AddDays(-((($dow - 1) + 7) % 7))
$capturedThisWeek = ($null -ne $fc) -and ($fc.Date -ge $weekMon)
$capturedToday    = ($null -ne $fc) -and ($fc.Date -eq $today.Date)
# An early capture is not proof of a good capture. cfbvictorymodel.com may not have
# refreshed the coming weekend's numbers yet on Monday, so a Monday snapshot can hold
# last week's figures. Going quiet on it would let a stale capture pass for a done
# week - so keep surfacing a re-check until Wednesday, by which point the source has
# certainly refreshed. Softer than DUE: it means "verify", not "you missed it".
$inRecheckWindow = $capturedThisWeek -and (-not $capturedToday) -and ($dow -ge 1) -and ($dow -le 3)
$rituals += [pscustomobject]@{
    Name    = "forecast-capture"
    Command = "/forecast-capture"
    Last    = if ($fc) { $fc.Date.ToString('yyyy-MM-dd') } else { "never" }
    Days    = $fcDays
    Status  = if (-not $inSeason)        { "OK" }
              elseif ($inRecheckWindow)  { "RECHECK" }  # captured early - confirm it is not stale
              elseif ($capturedThisWeek) { "OK" }
              elseif ($dow -eq 1)        { "DUE" }      # Monday - the nag day
              elseif ($dow -ge 2)        { "OVERDUE" }  # Tue-Sat - kickoff is coming
              else                       { "OK" }       # Sunday - games played, week gone
    Why     = if (-not $inSeason) {
                  "outside the season window ($($SeasonStart.ToString('yyyy-MM-dd')) to $($SeasonEnd.ToString('yyyy-MM-dd'))) - nothing to capture"
              } elseif ($inRecheckWindow) {
                  "captured $($fc.Date.ToString('yyyy-MM-dd')), before the source may have refreshed for this weekend - re-run to confirm the numbers are current"
              } elseif ($capturedThisWeek) {
                  "captured $($fc.Date.ToString('yyyy-MM-dd')) for the week of $($weekMon.ToString('yyyy-MM-dd'))"
              } else {
                  "the Chance of Victory column is overwritten with the result once a game is played - a week missed before Saturday is gone permanently"
              }
}

